        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by using an incorrect define (`NSEC_PER_MSEC - 1`) for rounding the `start_time`, which led to the time being rounded down to the past second boundary instead of rounding up to the next top of the second. This incorrect calculation prevented the expected 1PPS output from being generated.

        Commit message:
        ice: Fix perout start time rounding

Internal tests found out that the latest code doesn't bring up 1PPS out
as expected. As a result of incorrect define used to round the time up
the time was round down to the past second boundary.

Fix define used for rounding to properly round up to the next Top of
second in ice_ptp_cfg_clkout to fix it.

Fixes: 172db5f91d5f ("ice: add support for auxiliary input/output pins")
Signed-off-by: Maciej Machnikowski <maciej.machnikowski@intel.com>
Tested-by: Sunitha Mekala <sunithax.d.mekala@intel.com>
Signed-off-by: Tony Nguyen <anthony.l.nguyen@intel.com>
Link: https://lore.kernel.org/r/20210813165018.2196013-1-anthony.l.nguyen@intel.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>  

        Patch:
          */
 static int ice_ptp_cfg_clkout(struct ice_pf *pf, unsigned int chan,
 			      struct ice_perout_channel *config, bool store)
 {
 	u64 current_time, period, start_time, phase;
 	struct ice_hw *hw = &pf->hw;
 	u32 func, val, gpio_pin;
 	u8 tmr_idx;

 	tmr_idx = hw->func_caps.ts_func_info.tmr_index_owned;

 	/* 0. Reset mode & out_en in AUX_OUT */
 	wr32(hw, GLTSYN_AUX_OUT(chan, tmr_idx), 0);

 	/* If we're disabling the output, clear out CLKO and TGT and keep
 	 * output level low
 	 */
 	if (!config || !config->ena) {
 		wr32(hw, GLTSYN_CLKO(chan, tmr_idx), 0);
 		wr32(hw, GLTSYN_TGT_L(chan, tmr_idx), 0);
 		wr32(hw, GLTSYN_TGT_H(chan, tmr_idx), 0);

 		val = GLGEN_GPIO_CTL_PIN_DIR_M;
 		gpio_pin = pf->ptp.perout_channels[chan].gpio_pin;
 		wr32(hw, GLGEN_GPIO_CTL(gpio_pin), val);

 		/* Store the value if requested */
 		if (store)
 			memset(&pf->ptp.perout_channels[chan], 0,
 			       sizeof(struct ice_perout_channel));

 		return 0;
 	}
 	period = config->period;
 	start_time = config->start_time;
 	div64_u64_rem(start_time, period, &phase);
 	gpio_pin = config->gpio_pin;

 	/* 1. Write clkout with half of required period value */
 	if (period & 0x1) {
 		dev_err(ice_pf_to_dev(pf), "CLK Period must be an even value\n");
 		goto err;
 	}

 	period >>= 1;

 	/* For proper operation, the GLTSYN_CLKO must be larger than clock tick
 	 */
 #define MIN_PULSE 3
 	if (period <= MIN_PULSE || period > U32_MAX) {
 		dev_err(ice_pf_to_dev(pf), "CLK Period must be > %d && < 2^33",
 			MIN_PULSE * 2);
 		goto err;
 	}

 	wr32(hw, GLTSYN_CLKO(chan, tmr_idx), lower_32_bits(period));

 	/* Allow time for programming before start_time is hit */
 	current_time = ice_ptp_read_src_clk_reg(pf, NULL);

 	/* if start time is in the past start the timer at the nearest second
 	 * maintaining phase
 	 */
 	if (start_time < current_time)
-		start_time = div64_u64(current_time + NSEC_PER_MSEC - 1,
+		start_time = div64_u64(current_time + NSEC_PER_SEC - 1,
 				       NSEC_PER_SEC) * NSEC_PER_SEC + phase;

 	start_time -= E810_OUT_PROP_DELAY_NS;

 	/* 2. Write TARGET time */
 	wr32(hw, GLTSYN_TGT_L(chan, tmr_idx), lower_32_bits(start_time));
 	wr32(hw, GLTSYN_TGT_H(chan, tmr_idx), upper_32_bits(start_time));

 	/* 3. Write AUX_OUT register */
 	val = GLTSYN_AUX_OUT_0_OUT_ENA_M | GLTSYN_AUX_OUT_0_OUTMOD_M;
 	wr32(hw, GLTSYN_AUX_OUT(chan, tmr_idx), val);

 	/* 4. write GPIO CTL reg */
 	func = 8 + chan + (tmr_idx * 4);
 	val = GLGEN_GPIO_CTL_PIN_DIR_M |
 	      ((func << GLGEN_GPIO_CTL_PIN_FUNC_S) & GLGEN_GPIO_CTL_PIN_FUNC_M);
 	wr32(hw, GLGEN_GPIO_CTL(gpio_pin), val);

 	/* Store the value if requested */
 	if (store) {
 		memcpy(&pf->ptp.perout_channels[chan], config,
 		       sizeof(struct ice_perout_channel));
 		pf->ptp.perout_channels[chan].start_time = phase;
 	}

 	return 0;
 err:
 	dev_err(ice_pf_to_dev(pf), "PTP failed to cfg per_clk\n");
 	return -EFAULT;
 }



